function analyzeInspectionMonths(interval, skippedMonth) {
  let count = 0;
  let total = 0;
  for (let month = 1; month <= 12; month += 1) {
    if (month === skippedMonth) continue;
    if (month % interval !== 0) continue;
    count += 1;
    total += month;
  }
  return { count, total };
}
